import React from "react";
import { FaSearch, FaFilter } from "react-icons/fa";
import TechnicianItem from "./TechnicianItemComponent";
import FilterSheet from "./FilterSheetComponent";
import AuthCheck from "./AuthCheckComponent";

const API_URL = "https://iranaserviceapp.ir/test/api";

class TechniciansPage extends React.Component {
  constructor(props) {
    super(props);

    this.state = {
      technicians: [],
      searchTerm: "",
      isFilterOpen: false,
      filterProvince: "",
      filterCity: "",
      filterSpecialty: "",
      loading: true,
      authenticated: false,
    };

    this.handleSearchChange = this.handleSearchChange.bind(this);
    this.openFilter = this.openFilter.bind(this);
    this.closeFilter = this.closeFilter.bind(this);
    this.applyFilter = this.applyFilter.bind(this);
    this.handleDelete = this.handleDelete.bind(this);
    this.handleToggleStatus = this.handleToggleStatus.bind(this);
    this.handleDetails = this.handleDetails.bind(this);
  }

  componentDidMount() {
    if (!AuthCheck()) {
      return;
    }

    this.setState(
      {
        authenticated: true,
      },
      () => {
        this.getTechnicians();
      }
    );
  }

  // دریافت لیست تعمیرکارها
  getTechnicians = () => {
    const token = localStorage.getItem("token");

    this.setState({
      loading: true,
    });

    fetch(`${API_URL}/users`, {
      method: "GET",
      headers: {
        Accept: "application/json",
        Authorization: `Bearer ${token}`,
      },
    })
      .then((response) => {
        if (!response.ok) {
          throw new Error(`HTTP Error: ${response.status}`);
        }

        return response.json();
      })
      .then((data) => {
        console.log("USERS:", data);

        /*
         * با توجه به ساختار API ممکن است لیست داخل users باشد.
         */
        const users = Array.isArray(data.users)
          ? data.users
          : Array.isArray(data)
          ? data
          : [];

        this.setState({
          technicians: users,
          loading: false,
        });
      })
      .catch((error) => {
        console.error("GET USERS ERROR:", error);

        this.setState({
          technicians: [],
          loading: false,
        });
      });
  };

  handleSearchChange(e) {
    this.setState({
      searchTerm: e.target.value,
    });
  }

  openFilter() {
    this.setState({
      isFilterOpen: true,
    });
  }

  closeFilter() {
    this.setState({
      isFilterOpen: false,
    });
  }

  applyFilter() {
    this.closeFilter();
  }

  // حذف تعمیرکار
  handleDelete(id) {
    const token = localStorage.getItem("token");

    fetch(`${API_URL}/delete`, {
      method: "POST",

      headers: {
        "Content-Type": "application/json",
        Accept: "application/json",
        Authorization: `Bearer ${token}`,
      },

      body: JSON.stringify({
        id: id,
      }),
    })
      .then((response) => {
        if (!response.ok) {
          throw new Error(`HTTP Error: ${response.status}`);
        }

        return response.json();
      })
      .then((data) => {
        console.log("DELETE USER:", data);

        /*
         * بعد از حذف، دوباره لیست را از API می‌گیریم
         */
        this.getTechnicians();
      })
      .catch((error) => {
        console.error("DELETE USER ERROR:", error);
      });
  }

  // آزاد / مسدود کردن تعمیرکار
  handleToggleStatus(id, currentStatus) {
    const token = localStorage.getItem("token");

    fetch(`${API_URL}/active`, {
      method: "POST",

      headers: {
        "Content-Type": "application/json",
        Accept: "application/json",
        Authorization: `Bearer ${token}`,
      },

      body: JSON.stringify({
        id: id,
      }),
    })
      .then((response) => {
        if (!response.ok) {
          throw new Error(`HTTP Error: ${response.status}`);
        }

        return response.json();
      })
      .then((data) => {
        console.log("ACTIVE USER:", data);

        /*
         * دوباره لیست را از API می‌گیریم
         * تا وضعیت واقعی سرور نمایش داده شود.
         */
        this.getTechnicians();
      })
      .catch((error) => {
        console.error("ACTIVE USER ERROR:", error);
      });
  }

  handleDetails(id) {
    console.log("جزئیات تعمیرکار:", id);
  }

  render() {
    if (!this.state.authenticated) {
      return null;
    }

    const {
      technicians,
      searchTerm,
      isFilterOpen,
      filterProvince,
      filterCity,
      filterSpecialty,
      loading,
    } = this.state;

    const filteredTechnicians = technicians.filter((t) => {
      const name = `${t.name || ""} ${t.family || ""}`.trim();

      return name.includes(searchTerm.trim());
    });

    return (
      <div>
        <div className="container px-3 pt-3">
          {/* جستجو */}
          <div className="d-flex align-items-center gap-2 border rounded-pill px-3 py-2 mb-3 bg-white">
            <input
              type="text"
              placeholder="جستجو..."
              value={searchTerm}
              onChange={this.handleSearchChange}
              className="form-control border-0 shadow-none text-end p-0"
            />

            <FaSearch
              className="text-secondary"
              size={16}
            />
          </div>

          {/* فیلتر */}
          <div className="d-flex justify-content-end mb-3">
            <button
              type="button"
              onClick={this.openFilter}
              className="btn btn-light border rounded-pill d-flex align-items-center gap-2 px-3 py-2"
              style={{
                transition: "background-color 0.15s ease",
              }}
            >
              <span>فیلتر</span>

              <FaFilter
                className="text-secondary"
                size={14}
              />
            </button>
          </div>

          {/* عنوان */}
          <div className="bg-light text-center rounded-3 py-3 mb-1">
            <span className="text-primary fw-semibold">
              تعمیرکاران
            </span>
          </div>

          {/* Loading */}
          {loading ? (
            <div className="text-center text-muted py-5">
              در حال دریافت اطلاعات...
            </div>
          ) : (
            <div>
              {filteredTechnicians.map((tech) => (
                <TechnicianItem
                  key={tech.id}
                  technician={tech}
                  onDelete={this.handleDelete}
                  onToggleStatus={this.handleToggleStatus}
                  onDetails={this.handleDetails}
                />
              ))}

              {filteredTechnicians.length === 0 && (
                <div className="text-center text-muted py-5">
                  موردی یافت نشد
                </div>
              )}
            </div>
          )}
        </div>

        <FilterSheet
          isOpen={isFilterOpen}
          onClose={this.closeFilter}
          onApply={this.applyFilter}
          province={filterProvince}
          city={filterCity}
          specialty={filterSpecialty}
          onProvinceChange={(e) =>
            this.setState({
              filterProvince: e.target.value,
            })
          }
          onCityChange={(e) =>
            this.setState({
              filterCity: e.target.value,
            })
          }
          onSpecialtyChange={(e) =>
            this.setState({
              filterSpecialty: e.target.value,
            })
          }
        />
      </div>
    );
  }
}

export default TechniciansPage;
